import React, { useState, useEffect } from "react";
import axios from "axios";

/**
 * ==============================================================================
 * React - Session 11 (Question 1)
 * ==============================================================================
 * Task:
 * Install Axios in your React project and use it to fetch a list of trending
 * movies from the TMDB API (https://api.themoviedb.org/3/movie/popular) and
 * display the first 5 movie titles in a component.
 *
 * Hint: You can sign up for a free API key at TMDB or use a mock API like
 * https://jsonplaceholder.typicode.com/posts if you want to skip authentication.
 * ==============================================================================
 */
function TrendingMovies() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [apiSource, setApiSource] = useState("");
  const [apiKeyInput, setApiKeyInput] = useState("");

  // Default fallback trending titles for mock demonstration
  const fallbackTitles = [
    { id: 1, title: "Oppenheimer (2023)", rating: "8.9" },
    { id: 2, title: "Interstellar (2014)", rating: "8.7" },
    { id: 3, title: "Inception (2010)", rating: "8.8" },
    { id: 4, title: "The Dark Knight (2008)", rating: "9.0" },
    { id: 5, title: "Dune: Part Two (2024)", rating: "8.6" },
  ];

  // Fetch function using Axios
  const fetchTrendingMovies = async (customKey = "") => {
    setLoading(true);
    setError(null);

    const key = customKey.trim();

    // 1. If TMDB API key is provided, fetch directly from TMDB API
    if (key) {
      try {
        const response = await axios.get(
          "https://api.themoviedb.org/3/movie/popular",
          {
            params: {
              api_key: key,
            },
          }
        );

        // Display the first 5 movie titles using slice(0, 5)
        const first5Movies = response.data.results.slice(0, 5).map((m) => ({
          id: m.id,
          title: m.title,
          rating: m.vote_average ? m.vote_average.toFixed(1) : "N/A",
          releaseDate: m.release_date,
        }));

        setMovies(first5Movies);
        setApiSource("TMDB Official API (api.themoviedb.org)");
        setLoading(false);
        return;
      } catch (err) {
        console.warn("TMDB API request failed, falling back to mock API:", err.message);
        setError("TMDB API Key invalid or request failed. Loaded mock data instead.");
      }
    }

    // 2. Fallback / No Auth mode: Fetch with Axios from mock API (as instructed in Hint)
    try {
      const response = await axios.get(
        "https://jsonplaceholder.typicode.com/posts?_limit=5"
      );

      // Map response to first 5 movie titles
      const first5Movies = response.data.slice(0, 5).map((item, idx) => ({
        id: item.id,
        title: fallbackTitles[idx]?.title || `Trending Movie: ${item.title.substring(0, 25)}...`,
        rating: fallbackTitles[idx]?.rating || "8.5",
        mockTitleRaw: item.title,
      }));

      setMovies(first5Movies);
      setApiSource("Mock API (jsonplaceholder.typicode.com - No Auth required)");
    } catch (err) {
      setError(err.message || "Failed to fetch data using Axios.");
    } finally {
      setLoading(false);
    }
  };

  // Run on initial mount
  useEffect(() => {
    fetchTrendingMovies();
  }, []);

  const handleKeySubmit = (e) => {
    e.preventDefault();
    fetchTrendingMovies(apiKeyInput);
  };

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div style={styles.badge}>SESSION 11 - QUESTION 1</div>
        <h2 style={styles.title}>🎬 Trending Movies (Axios Fetch)</h2>
        <p style={styles.subtitle}>
          Fetching popular movies using <code>axios.get()</code> and displaying the top 5 titles.
        </p>
      </div>

      {/* Source Status & API Key Input Bar */}
      <div style={styles.statusBar}>
        <div style={styles.sourceInfo}>
          <span style={styles.sourceDot}>●</span>
          <span>Source: <strong>{apiSource || "Connecting..."}</strong></span>
        </div>

        {/* Optional TMDB API Key Input */}
        <form onSubmit={handleKeySubmit} style={styles.form}>
          <input
            type="text"
            placeholder="Enter TMDB API Key (Optional)"
            value={apiKeyInput}
            onChange={(e) => setApiKeyInput(e.target.value)}
            style={styles.input}
          />
          <button type="submit" style={styles.btnPrimary}>
            Fetch via TMDB
          </button>
          <button
            type="button"
            onClick={() => {
              setApiKeyInput("");
              fetchTrendingMovies("");
            }}
            style={styles.btnSecondary}
          >
            Reset to Mock
          </button>
        </form>
      </div>

      {/* Error Alert */}
      {error && (
        <div style={styles.alert}>
          ⚠️ {error}
        </div>
      )}

      {/* Loading State */}
      {loading ? (
        <div style={styles.loadingBox}>
          <div style={styles.spinner}>⏳</div>
          <p>Fetching first 5 trending movies via Axios...</p>
        </div>
      ) : (
        /* Movie List: First 5 Titles */
        <div style={styles.movieList}>
          <h3 style={styles.listHeading}>Top 5 Popular Movies:</h3>
          {movies.map((movie, index) => (
            <div key={movie.id} style={styles.movieCard}>
              <div style={styles.rankBadge}>#{index + 1}</div>
              <div style={styles.movieInfo}>
                <h4 style={styles.movieTitle}>{movie.title}</h4>
                {movie.releaseDate && (
                  <span style={styles.meta}>Release: {movie.releaseDate}</span>
                )}
              </div>
              <div style={styles.ratingBadge}>
                ⭐ {movie.rating}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// Styling
const styles = {
  container: {
    maxWidth: "800px",
    margin: "30px auto",
    padding: "28px",
    backgroundColor: "#ffffff",
    borderRadius: "16px",
    boxShadow: "0 10px 30px rgba(0, 0, 0, 0.08)",
    border: "1px solid #e2e8f0",
    fontFamily: "'Segoe UI', Roboto, sans-serif",
  },
  header: {
    marginBottom: "20px",
    borderBottom: "1px solid #e2e8f0",
    paddingBottom: "16px",
  },
  badge: {
    display: "inline-block",
    padding: "4px 10px",
    backgroundColor: "#eff6ff",
    color: "#2563eb",
    fontSize: "12px",
    fontWeight: "700",
    borderRadius: "20px",
    marginBottom: "8px",
    letterSpacing: "0.5px",
  },
  title: {
    margin: "0 0 6px 0",
    color: "#0f172a",
    fontSize: "24px",
    fontWeight: "800",
  },
  subtitle: {
    margin: 0,
    color: "#64748b",
    fontSize: "14px",
  },
  statusBar: {
    backgroundColor: "#f8fafc",
    padding: "14px 18px",
    borderRadius: "12px",
    marginBottom: "20px",
    display: "flex",
    flexDirection: "column",
    gap: "12px",
    border: "1px solid #e2e8f0",
  },
  sourceInfo: {
    fontSize: "13px",
    color: "#334155",
    display: "flex",
    alignItems: "center",
    gap: "6px",
  },
  sourceDot: {
    color: "#10b981",
    fontSize: "14px",
  },
  form: {
    display: "flex",
    flexWrap: "wrap",
    gap: "8px",
  },
  input: {
    flex: "1",
    minWidth: "220px",
    padding: "8px 12px",
    borderRadius: "8px",
    border: "1px solid #cbd5e1",
    fontSize: "13px",
    outline: "none",
  },
  btnPrimary: {
    backgroundColor: "#0284c7",
    color: "#ffffff",
    border: "none",
    padding: "8px 14px",
    borderRadius: "8px",
    fontSize: "13px",
    fontWeight: "600",
    cursor: "pointer",
  },
  btnSecondary: {
    backgroundColor: "#e2e8f0",
    color: "#334155",
    border: "none",
    padding: "8px 14px",
    borderRadius: "8px",
    fontSize: "13px",
    fontWeight: "600",
    cursor: "pointer",
  },
  alert: {
    backgroundColor: "#fef3c7",
    color: "#92400e",
    padding: "10px 14px",
    borderRadius: "8px",
    fontSize: "13px",
    marginBottom: "16px",
    border: "1px solid #fde68a",
  },
  loadingBox: {
    textAlign: "center",
    padding: "40px",
    color: "#64748b",
  },
  spinner: {
    fontSize: "30px",
    marginBottom: "10px",
  },
  listHeading: {
    fontSize: "16px",
    color: "#334155",
    margin: "0 0 14px 0",
    fontWeight: "700",
  },
  movieList: {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  },
  movieCard: {
